// ---- Events ----

/** Events sent by the Go side. Subscribe with `events.name.on(listener)`. */
export const events = {
  agentCreated: event<AgentView>("agent.created"),
  agentProfile: event<AgentView>("agent.profile"),
  agentDeleted: event<string>("agent.deleted"),
  agentStatus: event<StatusEvent>("agent.status"),
  agentDelta: event<DeltaEvent>("agent.delta"),
  agentMessage: event<MessageEvent>("agent.message"),
  agentError: event<ErrorEvent>("agent.error"),
  toolStart: event<ToolStartEvent>("tool.start"),
  /**
   * loop 内工具调用与运行结局。循环真的在跑，界面必须能看到，
   * 否则「停止」和「预算用尽」都只发生在后台，用户完全无感。
   */
  agentTool: event<AgentToolEvent>("agent.tool"),
  agentReasoning: event<AgentReasoningEvent>("agent.reasoning"),
  agentLoop: event<AgentLoopEvent>("agent.loop"),
  agentStopped: event<AgentStoppedEvent>("agent.stopped"),
  shellStart: event<ShellEvent>("shell.start"),
  shellResult: event<ShellResultEvent>("shell.result"),
  llmConfig: event<Config>("llm.config"),
  workdir: event<WorkDirEvent>("workdir"),
  /** 会话级配置变更：携带完整 AgentView，前端整体替换即可。 */
  agentConfig: event<AgentView>("agent.config"),
  /** 频道事件（由 API 直接 Emit，不走 emitToWindow 的 map 协议）。 */
  channelCreated: event<Channel>("channel.created"),
  channelDeleted: event<string>("channel.deleted"),
  channelMessage: event<ChannelMessage>("channel.message"),
  /** 知识库事件。 */
  knowledgeChanged: event<Note>("knowledge.changed"),
  knowledgeDeleted: event<string>("knowledge.deleted"),
  /**
   * 写操作审批：卡片出现、卡片结束。后端还会用 ListApprovals 补状态，
   * 保证界面刷新/重开后不会漏掉正在等的那一张。
   */
  toolApproval: event<ApprovalView>("tool.approval"),
  toolApprovalDone: event<string>("tool.approval.done"),
} as const;
